import type { ScenarioYears } from "./scenarios";

/**
 * How much of each barangay the model floods, by scenario.
 *
 * GENERATED by scripts/build-barangay-profiles.ts — do not edit by hand.
 * Regenerate with: pnpm --filter @davflood/hazard build:profiles
 *
 * Areas are square kilometres of MODELLED FLOOD FOOTPRINT, not a share of the
 * barangay: OpenStreetMap gives Davao's barangays as centroids rather than
 * boundaries for two thirds of them, so there is no denominator to divide by.
 * A figure in km² is honest; a percentage would be invented.
 *
 * All zeroes means the model does not flood that barangay in that scenario.
 * That is an answer, not missing data.
 */

export type BarangayStat = {
	/** km² in each depth band */
	low: number;
	medium: number;
	high: number;
	/** km² flooded in total */
	total: number;
	/** how many polygons make it up */
	zones: number;
};

